// --- CONSTANTS FOR DROPDOWNS ---
const ENTRANCE_STYLES: AnimationStyle[] = ['fade', 'slide', 'slam', 'zoom', 'typewriter', 'blur', 'glitch', 'elastic', 'scramble', 'spiral', 'inflate'];
const ACTIVE_STYLES: ActiveStyle[] = ['pulse', 'jitter', 'bounce', 'neon', 'wave', 'rotate', 'skew', 'pop', 'flash', 'float', 'shiver', 'glitch-shake', 'bass-bulge'];
const EXIT_STYLES: AnimationStyle[] = ['fade', 'slide', 'zoom', 'blur', 'sink', 'burn', 'shrink', 'drop'];

// Helper: Format seconds to SRT time format (00:00:00,000)
const formatToSRTTime = (seconds: number) => {
    const date = new Date(0);
    date.setMilliseconds(seconds * 1000);
    const iso = date.toISOString();
    // ISO format: 1970-01-01T00:00:00.000Z
    // We want: 00:00:00,000
    return iso.substr(11, 8) + ',' + iso.substr(20, 3);
};

